if(type==='ant')return `${defs}<g class="rig rig-ant"><path class="ant-leg l1" d="M-26-8-38 17m18-24-9 26M1-9l5 28m8-33 14 26" fill="none" stroke="#806453" stroke-width="3.5" stroke-linecap="round"/><ellipse cx="-28" cy="-19" rx="18" ry="15" fill="${fur}"/><ellipse cx="-4" cy="-22" rx="13" ry="12" fill="${fur}"/><g class="rig-head"><circle cx="22" cy="-31" r="20" fill="${fur}"/><path class="antennae" d="M13-47 8-63m23 16 10-16" stroke="#816454" stroke-width="3" stroke-linecap="round"/><circle cx="8" cy="-63" r="3" fill="#a48a65"/><circle cx="41" cy="-63" r="3" fill="#a48a65"/><g transform="translate(22 48) scale(.6)">${eyes(sleep,sad,scared)}<path d="M-5-62q5 7 10 0" stroke="#6f5047" stroke-width="2" fill="none"/></g></g></g>`;
