const bird=['bird','crow','duck','chick'].includes(type);
if(bird){return `${defs}<g class="rig rig-bird"><path d="M-11 5v18m-8 0H0m13-18v18m-8 0h19" fill="none" stroke="#c49a50" stroke-width="3.5" stroke-linecap="round"/><path class="bird-tail" d="M-26-20q-26-11-26-31 23 2 36 19" fill="${shade}"/><ellipse cy="-22" rx="34" ry="31" fill="${fur}"/><ellipse cx="8" cy="-15" rx="21" ry="20" fill="${cream}" opacity=".6"/><g class="rig-wing" transform="translate(-16 -29)"><path d="M-7 0q27-16 39 6-14 30-37 10Z" fill="${shade}" stroke="#5d7257" stroke-opacity=".12" stroke-width="1.5"/><path d="M1 9q13 7 22-1m-20 8q10 4 16 0" stroke="${base}" stroke-width="2" fill="none" opacity=".5"/></g><g class="rig-head"><circle cx="18" cy="-56" r="25" fill="${face}"/><path d="m39-57 26 10-27 7Z" fill="#dea25b" stroke="#bb874c" stroke-width="1"/><path d="M41-48h18" stroke="#c38b4c" stroke-width="1"/><g class="rig-blink"><ellipse cx="25" cy="-61" rx="6.3" ry="8" fill="${type==='crow'?'#e6eee0':'#fffdf1'}"/><ellipse cx="27" cy="-60" rx="3.3" ry="5" fill="#354947"/><circle cx="28" cy="-63" r="1.5" fill="#fff"/></g><ellipse cx="29" cy="-46" rx="6" ry="3.4" fill="#d2a084" opacity=".6"/><path d="M7-77q-3-14 7-16m0 16q7-17 12-11" fill="none" stroke="${base}" stroke-width="4" stroke-linecap="round"/></g></g>`}
if(type==='rabbit')headExtras=`${[-1,1].map(side=>`<g transform="translate(${side*17} -106)"><g class="rig-ear ${side<0?'left':'right'}"><path d="M-10 3Q-23-56-5-62 14-65 11 1Z" fill="${fur}" stroke="#cab992" stroke-opacity=".35" stroke-width="1.2"/><path d="M-4-6Q-14-46-4-49 4-45 4-8Z" fill="#e6b9ae"/></g></g>`).join('')}<path d="M-14-106q10-14 14-4 5-15 12-2" fill="${base}"/>`;
else if(type==='fox'){headExtras='<path d="m-30-96-7-37 30 23M11-110l27-24-3 41" fill="'+base+'" stroke="'+shade+'" stroke-width="2"/><path d="m-29-101-2-19 14 13m35 0 13-14-2 20" fill="#815d56"/>';back=`<g class="rig-tail"><path d="M-25 0q-76 15-66-58 37 6 48 35 20-6 25 4Z" fill="${fur}"/><path d="M-90-57q16 5 25 17l-9 24q-21-14-16-41" fill="#fff1d5"/></g>`;faceExtras='<path d="M-32-77q13 5 32 20 20-14 34-20-7 43-34 43-25-2-32-43" fill="#fff0d3"/>'}
else if(type==='lion'){back='<g class="lion-mane"><path d="M-38-105q-35-3-33 27-28 18-6 39-6 28 25 29 15 28 37 8 24 22 40-5 28-1 26-28 24-21 1-39 3-31-26-31-16-29-38 0Z" fill="#be8348"/><path d="M-38-98q-20 13-20 35m72-35q24 7 24 33" stroke="#dca45c" stroke-width="6" stroke-linecap="round" fill="none"/></g>';headExtras='<circle cx="-29" cy="-100" r="13" fill="#ddb367"/><circle cx="29" cy="-100" r="13" fill="#ddb367"/>'}
else if(type==='pig'){headExtras='<path d="M-30-93q-18-39 12-20l7 16m24-2q20-30 29-16l-9 25" fill="#e9a38f" stroke="#d38f80" stroke-width="1.4"/>';back='<path class="rig-tail" d="M29-10q36-16 19-27-15-3-7 10 8 5 15-3" fill="none" stroke="#d28f80" stroke-width="6" stroke-linecap="round"/>'}
else if(type==='mouse'){headExtras='<circle cx="-26" cy="-104" r="22" fill="#aaa9a7"/><circle cx="-26" cy="-104" r="14" fill="#d3b0aa"/><circle cx="27" cy="-104" r="21" fill="#aaa9a7"/><circle cx="27" cy="-104" r="13" fill="#d3b0aa"/>';back='<path class="rig-tail" d="M-27-2q-49 29-44-9 4-21-10-24" fill="none" stroke="#bfaaa2" stroke-width="5" stroke-linecap="round"/>'}
else if(type==='bear'){headExtras=`<circle cx="-27" cy="-103" r="16" fill="${shade}"/><circle cx="27" cy="-103" r="16" fill="${shade}"/><circle cx="-27" cy="-103" r="9" fill="#d5b394"/><circle cx="27" cy="-103" r="9" fill="#d5b394"/>`}
